router13.post("/schedule", authenticateUser, requireAdmin, async (req, res) => {
  try {
    const {
      title,
      body,
      userIds,
      targetRole,
      scheduledFor,
      recurrence,
      recurrenceEndDate,
      timezone,
      metadata
    } = req.body;
    const userId = req.userId;
    if (!title || !body || !userIds || !Array.isArray(userIds) || userIds.length === 0) {
      return res.status(400).json({
        error: "Invalid request",
        message: "title, body, and userIds array are required"
      });
    }
    if (!scheduledFor) {
      return res.status(400).json({
        error: "Invalid request",
        message: "scheduledFor date is required"
      });
    }
    const scheduledDate = new Date(scheduledFor);
    if (isNaN(scheduledDate.getTime())) {
      return res.status(400).json({
        error: "Invalid request",
        message: "scheduledFor must be a valid ISO date"
      });
    }
    const notificationId = await notificationScheduler.scheduleNotification(
      title,
      body,
      userIds,
      scheduledDate,
      userId,
      timezone || "UTC",
      recurrence,
      recurrenceEndDate ? new Date(recurrenceEndDate) : void 0,
      metadata || {}
    );
    log7.info("Notification scheduled via API", {
      notificationId,
      userCount: userIds.length,
      scheduledFor: scheduledDate
    });
    res.json({
      success: true,
      message: "Notification scheduled successfully",
      notificationId,
      scheduledFor: scheduledDate.toISOString()
    });
  } catch (error2) {
    log7.error("Failed to schedule notification", { error: error2 });
    res.status(500).json({
      error: "Failed to schedule notification",
      message: error2.message
    });
  }
});
