var ATTENDANCE_LATE_GRACE_MINUTES = 15;
async function canCloseBooking(bookingId, tenantId) {
  const query = { _id: bookingId };
  if (tenantId) query.tenantId = tenantId;
  const booking = await Booking.findOne(query);
  if (!booking) {
    return {
      eligible: false,
      blockingReasons: ["Booking not found"],
      nextActions: []
    };
  }
  const blockingReasons = [];
  const nextActions = [];
  if (booking.bookingType === "self_drive" && booking.securityDepositAmount) {
    const depositStatus = booking.securityDepositStatus || "pending";
    const finalDepositStates = ["refunded", "forfeited"];
    if (!finalDepositStates.includes(depositStatus)) {
      blockingReasons.push(
        `Self-drive security deposit is still ${depositStatus} (must be refunded or forfeited before closing)`
      );
      nextActions.push("Complete deposit settlement via self-drive refund/forfeiture process");
    }
  }
  const totalAmount = booking.totalAmount || 0;
  const advanceReceived = booking.advanceReceived || 0;
  const outstandingBalance = totalAmount - advanceReceived;
  if (outstandingBalance > 0) {
    blockingReasons.push(
      `Outstanding payment balance of ${outstandingBalance} remains (total: ${totalAmount}, received: ${advanceReceived})`
    );
    nextActions.push("Collect remaining payment or adjust pricing before closing");
  }
  try {
    const pendingRefunds = await PaymentTransaction2.findOne({
      bookingId: booking._id,
      tenantId: booking.tenantId,
      paymentType: "refund",
      status: "completed",
      createdAt: { $exists: true }
    });
    if (pendingRefunds && !pendingRefunds.reversalOf) {
      const refundAge = Date.now() - new Date(pendingRefunds.createdAt).getTime();
      const dayInMs = 24 * 60 * 60 * 1e3;
      if (refundAge < 7 * dayInMs) {
        blockingReasons.push(
          "Recent refund transaction exists (may not be settled to customer yet)"
        );
        nextActions.push("Confirm refund settlement before closing booking");
      }
    }
  } catch (err) {
    console.warn(
      `Warning: Could not check refund transactions for booking ${bookingId}:`,
      err?.message || err
    );
  }
  return {
    eligible: blockingReasons.length === 0,
    blockingReasons,
    nextActions
  };
}
function combineDateTime2(date2, time) {
  if (!date2) return null;
  const d = new Date(date2);
  if (isNaN(d.getTime())) return null;
  if (time && /^\d{1,2}:\d{2}/.test(time)) {
    const [h, m] = time.split(":").map(Number);
    d.setHours(h, m, 0, 0);
  }
  return d;
}
async function markDutyBasedAttendance(booking) {
  try {
    if (!booking.driverId) return;
    const actualStart = booking.actualStartDateTime;
    const dayKey = new Date(actualStart);
    dayKey.setHours(0, 0, 0, 0);
    const scheduled = combineDateTime2(booking.pickupDate, booking.pickupTime);
    let status = "on_duty";
    let lateDurationMinutes;
    if (scheduled) {
      const diffMinutes = (actualStart.getTime() - scheduled.getTime()) / 6e4;
      if (diffMinutes > ATTENDANCE_LATE_GRACE_MINUTES) {
        status = "late";
        lateDurationMinutes = Math.round(diffMinutes);
      }
    }
    await DriverAttendance.findOneAndUpdate(
      { tenantId: booking.tenantId, driverId: booking.driverId, date: dayKey },
      {
        $set: {
          status,
          actualCheckIn: actualStart,
          reportingTime: booking.pickupTime,
          dutyBookingId: booking._id,
          lateDurationMinutes,
          source: "duty_based"
        }
      },
      { upsert: true, new: true }
    );
  } catch (err) {
    console.error("Duty-based attendance marking failed (non-fatal):", err?.message || err);
  }
}
