var authenticateDriver = async (req, res, next) => {
  try {
    if (!req.session) {
      return res.status(401).json({ message: "Authentication required" });
    }
    const sessionId = req.session?.driverSessionId;
    if (!sessionId) {
      return res.status(401).json({ message: "Authentication required" });
    }
    const driver = await Driver.findOne({ sessionId });
    if (!driver) {
      req.session.destroy((err) => {
        if (err) console.error("Error destroying invalid driver session:", err);
      });
      return res.status(401).json({ message: "Invalid session" });
    }
    req.driverId = driver._id.toString();
    req.driver = driver;
    next();
  } catch (error2) {
    console.error("Driver authentication error:", error2);
    res.status(500).json({ message: "Authentication error" });
  }
};

