    try {
      const { mobile } = req.query;
      if (!mobile) {
        return res.status(400).json({ message: "Mobile number required" });
      }
      const { normalizeIndianPhone: normalizeIndianPhone3 } = await Promise.resolve().then(() => (init_phone_normalization(), phone_normalization_exports));
      const normalized = normalizeIndianPhone3(mobile);
      if (!normalized) {
        return res.status(400).json({ message: "Invalid phone format" });
      }
      const db2 = await storage.getDb();
      const customer = await db2.collection("customers").findOne({
        tenantId: new mongoose118.Types.ObjectId(req.tenantId),
        primaryMobile: normalized
      });
      if (customer) {
        return res.json({
          found: true,
          customer: {
            _id: customer._id,
            name: customer.name,
            mobile: customer.primaryMobile,
            email: customer.email,
            bookingCount: customer.totalBookings || 0,
            lastBookingDate: customer.lastBookingDate,
            totalSpending: customer.totalSpending || 0
          }
        });
      }
      const aliasMatch = await db2.collection("customers").findOne({
        tenantId: new mongoose118.Types.ObjectId(req.tenantId),
        $or: [
          { alternateMobile: normalized },
          { whatsappNumber: normalized },
          { phoneAliases: normalized }
        ]
      });
      if (aliasMatch) {
        return res.json({
          found: true,
          customer: {
            _id: aliasMatch._id,
            name: aliasMatch.name,
            mobile: aliasMatch.primaryMobile,
            email: aliasMatch.email,
            bookingCount: aliasMatch.totalBookings || 0,
            lastBookingDate: aliasMatch.lastBookingDate,
            totalSpending: aliasMatch.totalSpending || 0,
            aliasMatch: true
          }
        });
      }
      return res.json({
        found: false,
        mobile: normalized
      });
    } catch (error2) {
      res.status(500).json({ message: error2.message });
    }
