  app2.post("/api/bookings/test-whatsapp", authenticateUser, requireTenant, async (req, res) => {
    try {
      const { bookingId } = req.body;
      const booking = await storage.client?.db("fleetpro").collection("bookings").findOne({ _id: new mongoose118.Types.ObjectId(bookingId), tenantId: req.tenantId });
      if (!booking) {
        return res.status(404).json({ message: "Booking not found" });
      }
      const tenant = await storage.client?.db("fleetpro").collection("tenantWhatsAppProfiles").findOne({ tenantId: req.tenantId });
      if (!tenant?.isActive) {
        return res.status(400).json({ message: "WhatsApp not configured for tenant" });
      }
      let driver, vehicle, payment;
      if (booking.driverId) {
        driver = await storage.client?.db("fleetpro").collection("drivers").findOne({ _id: new mongoose118.Types.ObjectId(booking.driverId) });
      }
      if (booking.vehicleId) {
        vehicle = await storage.client?.db("fleetpro").collection("vehicles").findOne({ _id: new mongoose118.Types.ObjectId(booking.vehicleId) });
      }
      payment = await storage.client?.db("fleetpro").collection("bookingPayments").findOne({ bookingId: booking._id });
      const BookingWhatsAppIntegration2 = (await Promise.resolve().then(() => (init_booking_whatsapp_integration(), booking_whatsapp_integration_exports))).default;
      await BookingWhatsAppIntegration2.handleBookingConfirmed({
        tenantId: req.tenantId,
        bookingId: booking._id.toString(),
        eventType: "BOOKING_CONFIRMED",
        booking,
        driver,
        vehicle,
        payment,
        tenant
      });
      res.json({ success: true, message: "WhatsApp messages queued for sending" });
    } catch (error2) {
      res.status(500).json({ message: error2.message });
    }
  });
